const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// Color palette: Midnight Executive (navy/ice blue/white) - data-forward, professional
const COLORS = {
  primary: "1E2761",      // navy
  secondary: "CADCFC",    // ice blue
  accent: "FFFFFF",       // white
  dark: "0F1535",         // darker navy
  text: "1E293B",         // slate
  muted: "64748B",        // slate muted
  lightBg: "F8FAFC",      // very light slate
  chartBar: "1E2761",     // navy bars
  chartBarAlt: "3B4F9F",  // lighter navy
  chartBarOpen: "0891B2", // teal for open-weight
  success: "059669",      // green
  warning: "D97706",      // amber
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Artificial Analysis";
pres.title = "AI Model Landscape April 2026";
pres.subject = "Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models";

// Helper: fresh shadow factory
const makeShadow = (opacity = 0.12) => ({
  type: "outer",
  color: "000000",
  blur: 6,
  offset: 2,
  angle: 135,
  opacity,
});

// =============================
// SLIDE 1: TITLE
// =============================
const slide1 = pres.addSlide();
slide1.background = { color: COLORS.primary };

// Subtle top accent bar
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: "100%", h: 0.08,
  fill: { color: COLORS.secondary },
});

// Main title
slide1.addText("AI Model Landscape April 2026", {
  x: 0.6, y: 1.6, w: 8.8, h: 0.9,
  fontSize: 44, bold: true, color: COLORS.accent,
  fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
});

// Subtitle
slide1.addText("Benchmarking Intelligence, Speed, and Cost Across 11 Frontier Models", {
  x: 0.6, y: 2.5, w: 8.8, h: 0.6,
  fontSize: 20, color: COLORS.secondary,
  fontFace: "Calibri Light", align: "left", valign: "top", margin: 0,
});

// Divider line
slide1.addShape(pres.shapes.LINE, {
  x: 0.6, y: 3.2, w: 2.5, h: 0,
  line: { color: COLORS.secondary, width: 2 },
});

// Source + date block
slide1.addText("Data: Artificial Analysis  |  April 2026", {
  x: 0.6, y: 3.5, w: 8.8, h: 0.4,
  fontSize: 14, color: COLORS.secondary,
  fontFace: "Calibri Light", align: "left", valign: "middle", margin: 0,
});

// Bottom stat callouts
const statCards = [
  { label: "Models Benchmarked", value: "11" },
  { label: "Intelligence Tie", value: "57" },
  { label: "Price Spread", value: "33x" },
];
statCards.forEach((card, i) => {
  const x = 0.6 + i * 2.8;
  slide1.addShape(pres.shapes.RECTANGLE, {
    x, y: 4.3, w: 2.4, h: 1.0,
    fill: { color: COLORS.dark, transparency: 40 },
    rectRadius: 0.06,
  });
  slide1.addText(card.value, {
    x, y: 4.35, w: 2.4, h: 0.55,
    fontSize: 32, bold: true, color: COLORS.accent,
    align: "center", valign: "middle", margin: 0,
  });
  slide1.addText(card.label, {
    x, y: 4.85, w: 2.4, h: 0.4,
    fontSize: 12, color: COLORS.secondary,
    align: "center", valign: "middle", margin: 0,
  });
});

// =============================
// SLIDE 2: INTELLIGENCE
// =============================
const slide2 = pres.addSlide();
slide2.background = { color: COLORS.lightBg };

// Header background
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: "100%", h: 1.0,
  fill: { color: COLORS.primary },
});
slide2.addText("Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57", {
  x: 0.5, y: 0.25, w: 9.0, h: 0.6,
  fontSize: 28, bold: true, color: COLORS.accent,
  align: "left", valign: "middle", margin: 0,
});

// Intelligence data (11 models)
const intelModels = [
  { name: "Gemini 3.1 Pro Preview", provider: "Google", score: 57 },
  { name: "GPT-5.4 (xhigh)", provider: "OpenAI", score: 57 },
  { name: "Claude Opus 4.6 (max)", provider: "Anthropic", score: 53 },
  { name: "Muse Spark", provider: "Meta", score: 52 },
  { name: "Claude Sonnet 4.6 (max)", provider: "Anthropic", score: 52 },
  { name: "GLM-5.1", provider: "Z AI", score: 51 },
  { name: "Grok 4.20 0309 v2", provider: "xAI", score: 49 },
  { name: "Gemini 3 Flash", provider: "Google", score: 46 },
  { name: "DeepSeek V3.2", provider: "DeepSeek", score: 42 },
  { name: "NVIDIA Nemotron 3 Super", provider: "NVIDIA", score: 36 },
  { name: "gpt-oss-120B (high)", provider: "OpenAI", score: 33 },
];

// Horizontal bar chart
const intelLabels = intelModels.map(m => m.name);
const intelValues = intelModels.map(m => m.score);

slide2.addChart(pres.charts.BAR, [{
  name: "Intelligence Index",
  labels: intelLabels,
  values: intelValues,
}], {
  x: 0.4, y: 1.2, w: 9.2, h: 3.6,
  barDir: "bar",
  barGrouping: "clustered",
  chartColors: [COLORS.chartBar],
  chartArea: { fill: { color: COLORS.lightBg }, roundedCorners: false },
  catAxisLabelColor: COLORS.text,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.text,
  dataLabelFontSize: 10,
  showLegend: false,
  catAxisLabelFontSize: 9,
  valAxisLabelFontSize: 9,
  valAxisMaxVal: 65,
  valAxisMinVal: 0,
  title: "Intelligence Index Score (Higher = Stronger)",
  titleFontSize: 12,
  titleColor: COLORS.muted,
  titleBold: false,
});

// Insight box
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.4, y: 5.0, w: 9.2, h: 0.45,
  fill: { color: COLORS.secondary },
});
slide2.addText("Google and OpenAI are neck-and-neck at the frontier. Anthropic's Claude Opus 4.6 trails by 4 points, while Meta's Muse Spark enters at a strong 52.", {
  x: 0.55, y: 5.0, w: 8.9, h: 0.45,
  fontSize: 13, color: COLORS.primary,
  align: "left", valign: "middle", margin: 0,
});

// =============================
// SLIDE 3: SPEED
// =============================
const slide3 = pres.addSlide();
slide3.background = { color: COLORS.lightBg };

slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: "100%", h: 1.0,
  fill: { color: COLORS.primary },
});
slide3.addText("gpt-oss-120B Tops Output Speed at 218 Tokens/s — More Than 4x Faster Than Claude Opus 4.6", {
  x: 0.5, y: 0.18, w: 9.0, h: 0.7,
  fontSize: 26, bold: true, color: COLORS.accent,
  align: "left", valign: "middle", margin: 0,
});

const speedModels = [
  { name: "gpt-oss-120B (high)", speed: 218 },
  { name: "Grok 4.20 0309 v2", speed: 188 },
  { name: "NVIDIA Nemotron 3 Super", speed: 172 },
  { name: "Gemini 3 Flash", speed: 153 },
  { name: "Gemini 3.1 Pro Preview", speed: 118 },
  { name: "GPT-5.4 (xhigh)", speed: 83 },
  { name: "GLM-5.1", speed: 64 },
  { name: "Claude Sonnet 4.6 (max)", speed: 63 },
  { name: "Claude Opus 4.6 (max)", speed: 49 },
  { name: "DeepSeek V3.2", speed: 46 },
];

slide3.addChart(pres.charts.BAR, [{
  name: "Output Tokens/s",
  labels: speedModels.map(m => m.name),
  values: speedModels.map(m => m.speed),
}], {
  x: 0.4, y: 1.2, w: 9.2, h: 3.6,
  barDir: "bar",
  barGrouping: "clustered",
  chartColors: [COLORS.chartBarOpen],
  chartArea: { fill: { color: COLORS.lightBg }, roundedCorners: false },
  catAxisLabelColor: COLORS.text,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.text,
  dataLabelFontSize: 10,
  showLegend: false,
  catAxisLabelFontSize: 9,
  valAxisLabelFontSize: 9,
  valAxisMaxVal: 250,
  valAxisMinVal: 0,
  title: "Output Tokens per Second (Higher = Faster)",
  titleFontSize: 12,
  titleColor: COLORS.muted,
  titleBold: false,
});

slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.4, y: 5.0, w: 9.2, h: 0.45,
  fill: { color: COLORS.secondary },
});
slide3.addText("The fastest model outputs 218 tokens/s — more than 4x Claude Opus 4.6 and nearly 5x DeepSeek V3.2. The two intelligence leaders sit in the middle at 118 and 83 tokens/s.", {
  x: 0.55, y: 5.0, w: 8.9, h: 0.45,
  fontSize: 13, color: COLORS.primary,
  align: "left", valign: "middle", margin: 0,
});

// =============================
// SLIDE 4: PRICING
// =============================
const slide4 = pres.addSlide();
slide4.background = { color: COLORS.lightBg };

slide4.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: "100%", h: 1.0,
  fill: { color: COLORS.primary },
});
slide4.addText("From $0.30 to $10 per Million Tokens: A 33x Pricing Gap Across Models", {
  x: 0.5, y: 0.18, w: 9.0, h: 0.7,
  fontSize: 26, bold: true, color: COLORS.accent,
  align: "left", valign: "middle", margin: 0,
});

const priceModels = [
  { name: "gpt-oss-120B (high)", price: 0.30 },
  { name: "DeepSeek V3.2", price: 0.30 },
  { name: "NVIDIA Nemotron 3 Super", price: 0.40 },
  { name: "Gemini 3 Flash", price: 1.10 },
  { name: "GLM-5.1", price: 2.10 },
  { name: "Grok 4.20 0309 v2", price: 3.00 },
  { name: "Gemini 3.1 Pro Preview", price: 4.50 },
  { name: "GPT-5.4 (xhigh)", price: 5.60 },
  { name: "Claude Sonnet 4.6 (max)", price: 6.00 },
  { name: "Claude Opus 4.6 (max)", price: 10.00 },
];

slide4.addChart(pres.charts.BAR, [{
  name: "USD per 1M Tokens",
  labels: priceModels.map(m => m.name),
  values: priceModels.map(m => m.price),
}], {
  x: 0.4, y: 1.2, w: 9.2, h: 3.6,
  barDir: "bar",
  barGrouping: "clustered",
  chartColors: [COLORS.success],
  chartArea: { fill: { color: COLORS.lightBg }, roundedCorners: false },
  catAxisLabelColor: COLORS.text,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.text,
  dataLabelFontSize: 10,
  showLegend: false,
  catAxisLabelFontSize: 9,
  valAxisLabelFontSize: 9,
  valAxisMaxVal: 12,
  valAxisMinVal: 0,
  title: "Price per Million Tokens (USD, Lower = More Cost-Effective)",
  titleFontSize: 12,
  titleColor: COLORS.muted,
  titleBold: false,
});

slide4.addShape(pres.shapes.RECTANGLE, {
  x: 0.4, y: 5.0, w: 9.2, h: 0.45,
  fill: { color: COLORS.secondary },
});
slide4.addText("The cheapest options are over 33x less expensive than Claude Opus 4.6. Gemini 3 Flash offers compelling mid-range value at $1.10, pairing solid speed with reasonable intelligence.", {
  x: 0.55, y: 5.0, w: 8.9, h: 0.45,
  fontSize: 13, color: COLORS.primary,
  align: "left", valign: "middle", margin: 0,
});

// =============================
// SLIDE 5: TRADE-OFFS
// =============================
const slide5 = pres.addSlide();
slide5.background = { color: COLORS.lightBg };

slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: "100%", h: 1.0,
  fill: { color: COLORS.primary },
});
slide5.addText("No Model Wins on All Three Axes: Navigating the Intelligence-Efficiency-Cost Frontier", {
  x: 0.5, y: 0.18, w: 9.0, h: 0.7,
  fontSize: 24, bold: true, color: COLORS.accent,
  align: "left", valign: "middle", margin: 0,
});

// Scatter plot image (intelligence vs output tokens consumed)
const scatterImgPath = path.join(__dirname, "benchmark/assets/chart_intelligence_vs_output_tokens.jpg");
slide5.addImage({
  path: scatterImgPath,
  x: 0.4, y: 1.15, w: 5.0, h: 3.5,
  sizing: { type: "contain", w: 5.0, h: 3.5 },
});

// Caption under image
slide5.addText("Intelligence Index vs. Output Tokens Consumed During Evaluation", {
  x: 0.4, y: 4.7, w: 5.0, h: 0.3,
  fontSize: 10, color: COLORS.muted,
  align: "center", valign: "middle", margin: 0,
});

// Right side: Proprietary vs Open-Weight summary table
slide5.addText("Proprietary vs. Open-Weight Leaders", {
  x: 5.7, y: 1.2, w: 3.9, h: 0.4,
  fontSize: 16, bold: true, color: COLORS.primary,
  align: "left", valign: "middle", margin: 0,
});

const tableData = [
  [
    { text: "Metric", options: { bold: true, fill: { color: COLORS.primary }, color: COLORS.accent, align: "center" } },
    { text: "Proprietary Leader", options: { bold: true, fill: { color: COLORS.primary }, color: COLORS.accent, align: "center" } },
    { text: "Score", options: { bold: true, fill: { color: COLORS.primary }, color: COLORS.accent, align: "center" } },
