    { text: "$1.10", options: { bold: true, fill: { color: COLORS.lightBg }, align: "center" } },
    { text: "gpt-oss-120B (high)", options: { fill: { color: COLORS.lightBg }, align: "left" } },
    { text: "$0.30", options: { bold: true, fill: { color: COLORS.lightBg }, align: "center" } },
  ],
];

slide5.addTable(tableData, {
  x: 5.7, y: 1.7, w: 3.9, h: 1.8,
  border: { pt: 0.5, color: "CBD5E1" },
  colW: [1.3, 1.6, 0.7, 1.7, 0.7],
